tools.usage:
# comment
COMMAND parameters (x y) (x y);
COMMAND parameters \
        more_parameters;

tools.example:
# board outline 100 x 80 mm
GRID MM;
CHANGE LAYER DIMENSION;
LINE 0 (0 0) (100 0) (100 80) (0 80) (0 0);
VALUE R1 10k \
      R2 100k;
GRID LAST;

BRD:
GRID MM 0.5;
SET WIRE_BEND 2;
SCH:
GRID INCH 0.1;
SET CONFIRM OFF;

SHOW GND;
SHOW IC*;
SHOW @ C12;

tools.usage:
SIGNAL • •..
SIGNAL signal_name • •..
SIGNAL signal_name element_name pad_name..;

tools.example:
SIGNAL GND IC1 7 IC2 7 C1 2;
SIGNAL VCC IC1 14 IC2 14 C1 1;
SIGNAL CLK IC1 3 IC2 1;
RATSNEST;

REPOSITION R1 R2 C1;
MOVE R1>NAME (12.7 7.62);
CHANGE SIZE 1 (12.7 7.62);

SMD 2 1 NOCREAM 'TP' (0 0);
CHANGE LAYER TOP;
POLYGON 0.1 (-1 -1) (3 -1) (3 1) (-1 1) (-1 -1);

CHANGE LAYER tPlace;
CHANGE SIZE 1.27;
TEXT 'Rev B' R0 (5.08 5.08);

CHANGE LAYER NAMES;
TEXT '>NAME' (0 5.08);
CHANGE LAYER VALUES;
TEXT '>VALUE' (0 -7.62);

CHANGE FONT VECTOR;
CHANGE SIZE 1.5;
CHANGE RATIO 12;
CHANGE ALIGN TOP CENTER;
TEXT 'ABC' (20 20);

TEXT 'Do not populate; see BOM' (0 0);
TEXT 'Rev A\nDate 2026-09' (0 10);
TEXT 'red' (0 20);

tools.usage:
UPDATE
UPDATE;
UPDATE library_name..;
UPDATE footprint_name@library_name..;
UPDATE +@ | -@ [library_name..];
UPDATE old_library_name = new_library_name;

VALUE •..
VALUE value •..
VALUE name value ..
VALUE ON;
VALUE OFF;

tools.example:
VALUE R1 10k R2 100k;
VALUE R3   5.6k \
      C1   10uF \
      C2   22nF;

tools.usage:
VARIANT
VARIANT name part_name [NO]POPULATE [ value [ technology ] ];
VARIANT [ + | - ] name;

tools.example:
VARIANT +LITE;
VARIANT LITE R12 NOPOPULATE;
VARIANT LITE R7 POPULATE 4k7;
VARIANT LITE;
VARIANT '';

EDIT AMP.mod;
VARIANT +HIGH_GAIN;
VARIANT HIGH_GAIN R2 POPULATE 100k;

